// Generates a portable, offline HTML report. No game files or saves are changed.
const fs = require('fs');
const path = require('path');
const cp = require('child_process');
const root = path.resolve(__dirname, '..');
const findings = [];
const source = (file, needle, note = '') => {
  const lines = fs.readFileSync(path.join(root, file), 'utf8').split(/\r?\n/);
  const line = needle ? lines.findIndex(x => x.includes(needle)) + 1 : 1;
  if (!line) throw new Error('Evidence anchor not found: ' + file + ' / ' + needle);
  return {file, line, note};
};
const external = (url, note) => ({url, note});
function add(id, category, kind, priority, phase, title, problem, impact, action, done, evidence, dependencies = []) {
  findings.push({id, category, kind, priority, phase, title, problem, impact, action, done, evidence, dependencies});
}
